import json,glob
for f in sorted(glob.glob('da*_hist.json')):
    h=json.load(open(f)); s=h[-1]['score']; c=h[-1]['comet']; s0=h[0]['score']
    print(f[:-10].ljust(20), 'it',h[-1]['iter'], ' '.join('%s:%3.0f(%3.0f)/%.2f'%(b[:3],v['v_rmse'],s0[b]['v_rmse'],v['n_med_ratio']) for b,v in s.items()), '| comet n=%.2f v=%.0f F=%.2e'%(c['n'],c['v'],c['flux']))
"; tail -1 ../bench/out_literature/C_1deg/stdout.txt; cat enlil_exact_LE_T.out | tail -3",
  "description": "Tabulate DA results including 4D leave-out-STA"
}

{
  "command": "cd /mnt/c/Users/cabot/OneDrive/Documents/Research/Cambridge/X3I/mhd_llm/claude/src/py && ~/miniconda3/envs/mhd_claude/bin/python -c "
import sys,json; sys.path.insert(0,'.'); import numpy as np, run_helio as R, inputs as I
for nm in ('enlil_exact_LE_ccmc','enlil_exact_LE_ccmc_T0.558'):
    pr=R.probes(R.RUNS/nm); out=[]
    for b in ('earth','stereo_a','3i_atlas'):
        e=R.ccmc_evo(b); t=np.arange(I.tsec('2025-11-01'),I.tsec('2025-12-08'),3600.)
        ve=np.interp(t,e.t,e.v); vm=np.interp(t,pr[b].t,pr[b].v); ne=np.interp(t,e.t,e.n); nm_=np.interp(t,pr[b].t,pr[b].n)
        out.append('%s: r=%.2f rmse=%.0f bias=%+.0f nratio=%.2f rlogn=%.2f'%(b[:5],np.corrcoef(vm,ve)[0,1],np.sqrt(np.mean((vm-ve)**2)),np.mean(vm-ve),np.median(nm_/ne),np.corrcoef(np.log(nm_),np.log(ne))[0,1]))
    print(nm, ' | '.join(out))
"",
  "description": "Compare replica variants against ENLIL"
}

